      ACCEPT_TOKEN(anon_sym_InputError);
      END_STATE();
    case 173:
      ACCEPT_TOKEN(anon_sym_ParseError);
      END_STATE();
    case 174:
      ACCEPT_TOKEN(anon_sym_file_DOTlines);
      END_STATE();
    case 175:
      ACCEPT_TOKEN(anon_sym_BufferError);
      END_STATE();
    default:
      return false;
